// Generate arbitrary int inputs, then constrain b so that a+b stays within 32-bit int bounds
int a = *FUZZ_PARAM(int);
int candidate_b = *FUZZ_PARAM(int);

// We must avoid signed overflow/underflow. Compute the valid b range so that a+b fits in int.
// The API guarantees 32-bit signed int; use explicit 32-bit limits.
const long long INT32_MIN_LL = -2147483648LL;
const long long INT32_MAX_LL =  2147483647LL;

long long low = INT32_MIN_LL - (long long)a;   // minimal b to keep sum >= INT_MIN
long long high = INT32_MAX_LL - (long long)a;  // maximal b to keep sum <= INT_MAX

// Intersect with representable int range [INT_MIN, INT_MAX]
long long minB = (low < INT32_MIN_LL) ? INT32_MIN_LL : low;
long long maxB = (high > INT32_MAX_LL) ? INT32_MAX_LL : high;
if (minB > maxB) { FUZZ_BAIL(); }

// Clamp candidate_b into the safe range
long long b_ll = (long long)candidate_b;
if (b_ll < minB) b_ll = minB;
else if (b_ll > maxB) b_ll = maxB;
int b = (int)b_ll;

// Call the pure function; no side effects or state to track
int sum = kamyu_sum(a, b);

// Property: result must equal mathematical addition within int range
long long expected = (long long)a + (long long)b;
FUZZ_ASSERT(expected >= INT32_MIN_LL && expected <= INT32_MAX_LL, "a+b must be in int range");
FUZZ_ASSERT(sum == (int)expected, "kamyu_sum must equal a+b without overflow");
